import{_ as t,o as a,c as o,a6 as r}from"./chunks/framework.CA8SQds3.js";const p=JSON.parse('{"title":"Coverage cost","description":"What each coverage mode records, what leaves the machine, and what it costs in test time and CPU, measured on a large ASP.NET Core and Vue application and on synthetic pages.","frontmatter":{"title":"Coverage cost","description":"What each coverage mode records, what leaves the machine, and what it costs in test time and CPU, measured on a large ASP.NET Core and Vue application and on synthetic pages.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/reference/coverage-cost.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/reference/coverage-cost.html"}],["meta",{"property":"og:title","content":"Coverage cost | Piwi Dashboard"}],["meta",{"property":"og:description","content":"What each coverage mode records, what leaves the machine, and what it costs in test time and CPU, measured on a large ASP.NET Core and Vue application and on synthetic pages."}]]},"headers":[],"relativePath":"reference/coverage-cost.md","filePath":"reference/coverage-cost.md","lastUpdated":1792836493000}'),s={name:"reference/coverage-cost.md"};function n(i,e,d,h,c,l){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="coverage-cost" tabindex="-1">Coverage cost <a class="header-anchor" href="#coverage-cost" aria-label="Permalink to &quot;Coverage cost&quot;">​</a></h1><p>Coverage has two sides, each opt-in: the browser&#39;s, <a href="/features/code-reach.html">code reach</a>, and the backend&#39;s, <a href="/features/server-coverage.html">server coverage</a>. Each mode below records more than the one above it on its side.</p><h2 id="the-modes" tabindex="-1">The modes <a class="header-anchor" href="#the-modes" aria-label="Permalink to &quot;The modes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mode</th><th>Turn it on</th><th>Records per test</th><th>Leaves the machine</th></tr></thead><tbody><tr><td>Browser files</td><td><code>coverage.browser: &#39;files&#39;</code>, or <code>captureCodeReach: true</code></td><td>the application files whose functions ran</td><td>paths</td></tr><tr><td>Browser functions</td><td><code>coverage.browser: &#39;functions&#39;</code></td><td>also the start and end line of each function that ran</td><td>paths, line numbers, git blob ids</td></tr><tr><td>Server files</td><td><code>coverage.server: &#39;files&#39;</code>, with a coverage build</td><td>the backend files that ran</td><td>paths</td></tr><tr><td>Server functions</td><td><code>coverage.server: &#39;functions&#39;</code></td><td>also the start and end line of each function that ran</td><td>paths, line numbers, git blob ids</td></tr><tr><td>Server lines</td><td><code>coverage.server: &#39;lines&#39;</code></td><td>also the executed lines, and the run&#39;s executable lines</td><td>paths, line numbers, git blob ids</td></tr></tbody></table><p>Never source code, never hit counts. Each variable form (<code>PIWI_COVERAGE_BROWSER</code>, <code>PIWI_COVERAGE_SERVER</code>) fills the option the Playwright config leaves unset.</p><h2 id="on-a-large-asp-net-core-and-vue-application" tabindex="-1">On a large ASP.NET Core and Vue application <a class="header-anchor" href="#on-a-large-asp-net-core-and-vue-application" aria-label="Permalink to &quot;On a large ASP.NET Core and Vue application&quot;">​</a></h2><p>Against the same suite, on the same coverage build, with every coverage option off:</p><table tabindex="0"><thead><tr><th>Mode</th><th style="text-align:right;">UI tests</th><th style="text-align:right;">API tests</th><th style="text-align:right;">Chromium CPU</th><th style="text-align:right;">Backend CPU</th></tr></thead><tbody><tr><td>Server lines</td><td style="text-align:right;">+2% (−7 to +6%)</td><td style="text-align:right;">0%</td><td style="text-align:right;">−3%</td><td style="text-align:right;">−6%</td></tr><tr><td>Browser files</td><td style="text-align:right;">+40% (+38 to +58%)</td><td style="text-align:right;">−4%</td><td style="text-align:right;">+51%</td><td style="text-align:right;">+3%</td></tr><tr><td>Browser functions</td><td style="text-align:right;">+47% (+40 to +69%)</td><td style="text-align:right;">0%</td><td style="text-align:right;">+55%</td><td style="text-align:right;">+5%</td></tr><tr><td>Server lines and browser functions</td><td style="text-align:right;">+51% (+40 to +64%)</td><td style="text-align:right;">+4%</td><td style="text-align:right;">+63%</td><td style="text-align:right;">+11%</td></tr></tbody></table><ul><li><strong>UI tests:</strong> in each round, each UI test&#39;s time against its time in that round&#39;s pass with coverage off, and the median of those ratios; then the median over the rounds, their range in brackets. The UI tests that ran took 10 to 51 seconds with coverage off; with browser coverage, the 51-second one took about 72.</li><li><strong>CPU:</strong> the run&#39;s total for Chromium&#39;s renderer processes, and for the four backend processes, against the same round&#39;s pass with coverage off.</li><li><strong>Noise:</strong> the passes with coverage off alone varied by more than 10% from one round to the next, which is why each mode is compared within its round: read a difference under 10% as none.</li><li><strong>The coverage build itself,</strong> every option off, ran within 1% of a normal build of the same backend.</li><li><strong>Server files and server functions</strong> were not measured apart: the build records the same way at every granularity, which only decides what each test&#39;s report names.</li></ul><p><strong>The application:</strong> an ASP.NET Core backend serving four web front-ends, each a Vue 3 application its own Vite dev server serves, about 500 ES modules on a page, full page loads between screens, PostgreSQL. <strong>The suite:</strong> 18 tests, 6 driving the front-ends and 12 calling the backend through Playwright&#39;s <code>request</code> fixture, 3 workers, headless Chromium, on a 20-core machine. After a warm-up pass, rounds ran one pass of each mode in turn, so each mode ran three to five times.</p><p><strong>What the browser side spends.</strong> For each document a test loads, the debugger reports every script, the reporter reads the source of each application script its worker has not seen yet, and V8&#39;s precise coverage keeps a record of every function the page runs; as the test leaves the document, the reporter stops the page to read that record and resolves it to files. Each of these works on every module of every document, so the cost grows with the modules a page loads and with the full page loads a test makes: an application that loads its modules once, then navigates on the client, pays far less, as the synthetic pages below show. Files and functions cost about the same: both read the same record, functions only keep more of it.</p><h2 id="on-synthetic-pages" tabindex="-1">On synthetic pages <a class="header-anchor" href="#on-synthetic-pages" aria-label="Permalink to &quot;On synthetic pages&quot;">​</a></h2><p>Browser files, medians on a 4-core sandbox, headless Chromium, one page per test:</p><ul><li><strong>A script-heavy page</strong> (Vue&#39;s development build rendering a 1,000-row table 30 times, 400 ES modules): 1,128 ms to 1,220 ms per test, 8% more, and 16% for a worker&#39;s first test, where Playwright&#39;s <code>page.coverage</code> adds 50%.</li><li><strong>A light page</strong> (the reporter&#39;s capture benchmark, <code>npm run reporter:bench</code>): 61 to 103 ms more per test, where <code>page.coverage</code> adds 176 to 209 ms.</li></ul><p>Server coverage, on a prototype of the coverage package: under 2% of test duration on Microsoft&#39;s eShopOnWeb, whose CPU goes to the framework; up to 26% more backend CPU on an application written to spend its CPU in business logic, and 6% in its run-level mode. Functions cost about what lines cost: the cost is the recorder&#39;s call on every method call.</p><h2 id="choosing" tabindex="-1">Choosing <a class="header-anchor" href="#choosing" aria-label="Permalink to &quot;Choosing&quot;">​</a></h2><ul><li><strong>Server coverage</strong> can stay on in every run: against a backend that is not a coverage build, it collects nothing and costs nothing, so the build decides. On a coverage build, every granularity costs what lines cost, under 10% of the UI tests&#39; time: record lines, unless the reports&#39; size matters more than their detail.</li><li><strong>Browser coverage</strong> belongs in a scheduled run on a large application served by a dev server, where it adds 40 to 50% to the UI tests. Files and functions cost about the same, so a scheduled run may as well record functions. On an application that loads its modules once, it costs little enough to stay on.</li></ul>',17)])])}const u=t(s,[["render",n]]);export{p as __pageData,u as default};
